local function digestShape(value)
  return type(value) == "string" and #value == 64
    and value:match("^[0-9a-f]+$") ~= nil
end

-- Validate the complete composition before publishing either side. The
-- target's ten original events are retained byte-for-byte in the campaign;
-- only these six rows are appended after every collision check has passed.
function P.register(eventArchive, catalog)
  assert(type(eventArchive) == "table"
      and type(eventArchive.profile) == "function"
      and type(eventArchive.registerGiftProfiles) == "function",
    "cross-generation Gift Code Event Archive seam missing")
  assert(type(catalog) == "table"
      and catalog.schema == "ka-offline-gift-code-catalog/v1"
      and catalog.version == 1 and type(catalog.campaigns) == "table",
    "cross-generation Gift Code catalog seam missing")
  assert(#P.profiles == 6 and #P.events == 6,
    "cross-generation Gift Code owner must contain exactly six profiles")

  local campaign
  local seenEvents, seenDigests = {}, {}
  for _, row in ipairs(catalog.campaigns) do
    assert(type(row) == "table" and type(row.events) == "table",
      "invalid existing Gift Code campaign")
    if row.id == P.campaignId then
      assert(campaign == nil, "duplicate 6.6 Gift Code campaign")
      campaign = row
    end
    for _, event in ipairs(row.events) do
      assert(type(event.id) == "string" and not seenEvents[event.id],
        "duplicate existing Gift Code event")
      seenEvents[event.id] = true
      for _, digest in ipairs(event.digests or {}) do
        assert(digestShape(digest) and not seenDigests[digest],
          "invalid or duplicate existing Gift Code digest")
        seenDigests[digest] = true
      end
    end
  end
  assert(campaign and campaign.version == 1
      and campaign.buildId == P.buildId and campaign.status == "active",
    "6.6 private-RC Gift Code campaign identity drifted")
  local existingDigests = 0
  for _, event in ipairs(campaign.events) do
    existingDigests = existingDigests + #(event.digests or {})
  end
  assert(#campaign.events == 10 and existingDigests == 30000,
    "6.6 private-RC Gift Code baseline drifted")

  local selectedProfiles = {}
  for _, profile in ipairs(P.profiles) do
    assert(type(profile.id) == "string" and not selectedProfiles[profile.id]
        and eventArchive.profile(profile.id) == nil,
      "duplicate cross-generation Gift Code profile " .. tostring(profile.id))
    selectedProfiles[profile.id] = profile
  end
  local newDigests = 0
  for _, event in ipairs(P.events) do
    assert(selectedProfiles[event.profileId] and event.id == event.profileId
        and not seenEvents[event.id] and #(event.digests or {}) == 3000,
      "invalid cross-generation Gift Code event " .. tostring(event.id))
    seenEvents[event.id] = true
    for _, digest in ipairs(event.digests) do
      assert(digestShape(digest) and not seenDigests[digest],
        "duplicate cross-generation Gift Code digest")
      seenDigests[digest] = true
      newDigests = newDigests + 1
    end
  end
  assert(newDigests == 18000,
    "cross-generation Gift Code digest set must contain exactly 18000 entries")

  assert(eventArchive.registerGiftProfiles(P.profiles) == 6,
    "cross-generation Gift Code profile registration incomplete")
  for _, event in ipairs(P.events) do
    campaign.events[#campaign.events + 1] = event
  end
  return {
    profiles = 6, events = 6, digests = 18000,
    campaignEvents = #campaign.events,
    campaignDigests = existingDigests + newDigests,
  }
end

return P
